const body = $input.all()[0].json.body || {};
const events = body.events || [];
if (events.length === 0) return [{ json: { skip: true, reason: 'no events' } }];
const event = events[0];
if (event.type !== 'message' || event.message.type !== 'text') {
  return [{ json: { skip: true, reason: 'non-text ' + (event.message && event.message.type) } }];
}
const text = event.message.text || '';
// Optional in-chat robot selector: "@zenbo1 สวัสดี" or "robot:zenbo2 ..."
let mentionedRobot = null;
const at = text.match(/@([\w.-]+)/);
const col = text.match(/^(?:robot|zenbo)[:\s]+([\w.-]+)/i);
if (at) mentionedRobot = at[1];
else if (col) mentionedRobot = col[1];
return [{ json: {
  userMessage: text,
  mentionedRobot,
  replyToken: event.replyToken,
  userId: event.source && event.source.userId,
  groupId: event.source && event.source.groupId || null
} }];

// UserId -> robot_slug map (edit to bind LINE users to specific robots).
const USER_ROBOT_MAP = {};

const parse = $('📝 Parse LINE Event').first().json;
const robots = ($input.all()[0].json.robots || []);
let robotSlug = parse.mentionedRobot || USER_ROBOT_MAP[parse.userId] || null;
if (!robotSlug && robots.length) robotSlug = robots[0].robot_slug;
if (!robotSlug) throw new Error('No online Zenbo robot available');

return [{ json: {
  userMessage: parse.userMessage,
  replyToken: parse.replyToken,
  userId: parse.userId,
  robotSlug
} }];

const compile = $input.all()[0].json;
const payload = compile.compiled_payload || {};
const robot = $('🎯 Resolve Target Robot').first().json;
const emergency = !!payload.emergency;
// Build the dispatch body for /interact; strip the emergency flag (handled by /stop).
const dispatchBody = { ...payload, robot_slug: robot.robotSlug, source: 'n8n_line' };
delete dispatchBody.emergency;
return [{ json: {
  replyToken: robot.replyToken,
  userId: robot.userId,
  robotSlug: robot.robotSlug,
  emergency,
  dispatchBody,
  spokenText: payload.text || 'รับทราบคำสั่งเรียบร้อยแล้วครับ',
  face: payload.face || 'HAPPY',
  compilerSource: compile.compiler_source || 'local_fallback',
  originalCommand: compile.original_command || robot.userMessage
} }];

const info = $('🎨 Build Dispatch').first().json;
const dispatched = $input.all()[0] && $input.all()[0].json || {};
const headerColor = info.emergency ? '#DC2626' : '#2563EB';
const statusLine = info.emergency ? '🛑 หยุดฉุกเฉิน' : '✅ ส่งคำสั่งแล้ว';
const reply = {
  type: 'flex',
  altText: '🤖 ' + info.spokenText.substring(0, 60),
  contents: {
    type: 'bubble',
    size: 'kilo',
    header: { type: 'box', layout: 'vertical', backgroundColor: headerColor,
      contents: [{ type: 'text', text: '🤖 Zenbo · n8n', weight: 'bold', color: '#FFFFFF', size: 'md' }] },
    body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
      { type: 'text', text: '💬 "' + info.originalCommand + '"', size: 'xs', color: '#64748B', wrap: true },
      { type: 'separator', margin: 'sm' },
      { type: 'text', text: '🗣️ ' + info.spokenText, size: 'sm', weight: 'bold', color: '#1E293B', wrap: true },
      { type: 'box', layout: 'horizontal', spacing: 'sm', margin: 'md', contents: [
        { type: 'text', text: '😊 ' + info.face, size: 'xs', color: '#475569', flex: 1 },
        { type: 'text', text: statusLine, size: 'xs', color: info.emergency ? '#DC2626' : '#10B981', align: 'end' }
      ]},
      { type: 'text', text: '🤖 ' + info.robotSlug + ' · ' + info.compilerSource, size: 'xxs', color: '#94A3B8' }
    ]}
  }
};
return [{ json: { replyToken: info.replyToken, replyPayload: reply } }];
